message.content:
{"diagnosis": "Loopback receive returned 0xe0 instead of expected 0xa5, causing tohost FAIL 0xdead and uart data mismatch TRAP. Data/stop states advance when recv_divcnt > (cfg_divider >> 4), sampling ~16x too early instead of a full cfg_divider bit period. With divider 64 this samples inside start/early bits and corrupts recv_pattern. Root cause is lines 90 and 97 using (cfg_divider >> 4).", "patch_diff": "diff --git a/picosoc/simpleuart.v b/picosoc/simpleuart.v
--- a/picosoc/simpleuart.v
+++ b/picosoc/simpleuart.v
@@ -89,14 +89,14 @@
 				10: begin
-					if (recv_divcnt > (cfg_divider >> 4)) begin
+					if (recv_divcnt > cfg_divider) begin
 						recv_buf_data <= recv_pattern;
 						recv_buf_valid <= 1;
 						recv_state <= 0;
 					end
 				end
 				default: begin
-					if (recv_divcnt > (cfg_divider >> 4)) begin
+					if (recv_divcnt > cfg_divider) begin
 						recv_pattern <= {ser_rx, recv_pattern[7:1]};
 						recv_state <= recv_state + 1;
 						recv_divcnt <= 0;
 					end
 				end
", "expected": "tohost: PASS, uart loopback got 0xa5 want 0xa5 with no TRAP/mismatch"}

